, true);

$pdo->exec('SET FOREIGN_KEY_CHECKS=0');
$pending = $tables;
for ($pass = 1; $pass <= 3 && $pending; $pass++) {
    $failed = [];
    foreach ($pending as $name => $sql) {
        try { $pdo->exec($sql); echo "OK   $name\n"; }
        catch (Throwable $e) { $failed[$name] = $sql; echo "FAIL $name: " . $e->getMessage() . "\n"; }
    }
    $pending = $failed;
    if ($pending) echo "-- retrying --\n";
}
$pdo->exec('SET FOREIGN_KEY_CHECKS=1');
echo "\nTables in database: " . count($pdo->query('SHOW TABLES')->fetchAll()) . "\n";
echo "Now delete setup_tables.php from the repo.\n";
